"""Core service surface for StreamMill.

The frozen baseline only reports process health; that surface stays
unchanged. On top of it this module now implements named event-time
tumbling windows with explicit watermarks:

* streams are created with a positive ``window_ms`` and a non-negative
  ``allowed_lateness_ms``;
* events carry an integer ``timestamp_ms`` and a finite numeric ``value``
  and land in the left-closed, right-open window
  ``[floor(timestamp_ms / window_ms) * window_ms, +window_ms)``;
* a per-stream watermark only moves forward; once it reaches
  ``window_end_ms + allowed_lateness_ms`` the window is final, is
  emitted exactly once, and is retained for queries;
* events with ``timestamp_ms < watermark - allowed_lateness_ms`` are
  acknowledged but dropped without touching the aggregates.

Restart recovery, deduplication, joins, persistence and automatic
watermarks are explicitly out of scope.
"""

from __future__ import annotations

import threading

from . import __version__


class StreamExistsError(Exception):
    """Raised when creating a stream that already exists."""


class StreamNotFoundError(Exception):
    """Raised when addressing a stream that does not exist."""


class WatermarkRegressionError(Exception):
    """Raised when a new watermark would move the stream backwards."""


class _Stream:
    """Mutable state of one named stream. Guarded by the Service lock."""

    def __init__(self, name: str, window_ms: int, allowed_lateness_ms: int) -> None:
        self.name = name
        self.window_ms = window_ms
        self.allowed_lateness_ms = allowed_lateness_ms
        self.watermark: int | None = None
        # window_start_ms -> [count, sum]; only non-empty windows exist.
        self._windows: dict[int, list] = {}
        self._finalized: list[dict] = []
        self._finalized_starts: set[int] = set()

    def add_event(self, timestamp_ms: int, value: float) -> dict:
        if (
            self.watermark is not None
            and timestamp_ms < self.watermark - self.allowed_lateness_ms
        ):
            return {"dropped": True}
        start = (timestamp_ms // self.window_ms) * self.window_ms
        bucket = self._windows.setdefault(start, [0, 0])
        bucket[0] += 1
        bucket[1] += value
        return {"dropped": False}

    def advance_watermark(self, watermark_ms: int) -> list[dict]:
        if self.watermark is not None and watermark_ms < self.watermark:
            raise WatermarkRegressionError(
                f"watermark {watermark_ms} is below current {self.watermark}"
            )
        self.watermark = watermark_ms
        newly: list[dict] = []
        for start in sorted(self._windows):
            if start in self._finalized_starts:
                continue
            end = start + self.window_ms
            if watermark_ms >= end + self.allowed_lateness_ms:
                count, total = self._windows[start]
                newly.append(
                    {
                        "stream": self.name,
                        "window_start_ms": start,
                        "window_end_ms": end,
                        "count": count,
                        "sum": total,
                    }
                )
                self._finalized_starts.add(start)
        self._finalized.extend(newly)
        return newly

    def results(self) -> list[dict]:
        return [dict(row) for row in self._finalized]


class Service:
    """StreamMill service: health reporting plus windowed event aggregation."""

    name = "streammill"
    version = __version__

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._streams: dict[str, _Stream] = {}

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def create_stream(
        self, name: str, window_ms: int, allowed_lateness_ms: int
    ) -> dict:
        with self._lock:
            if name in self._streams:
                raise StreamExistsError(name)
            self._streams[name] = _Stream(name, window_ms, allowed_lateness_ms)
        return {
            "stream": name,
            "window_ms": window_ms,
            "allowed_lateness_ms": allowed_lateness_ms,
        }

    def add_event(self, name: str, timestamp_ms: int, value: float) -> dict:
        with self._lock:
            outcome = self._get(name).add_event(timestamp_ms, value)
        return {"stream": name, **outcome}

    def advance_watermark(self, name: str, watermark_ms: int) -> dict:
        with self._lock:
            finalized = self._get(name).advance_watermark(watermark_ms)
        return {"stream": name, "watermark_ms": watermark_ms, "finalized": finalized}

    def results(self, name: str) -> dict:
        with self._lock:
            rows = self._get(name).results()
        return {"stream": name, "results": rows}

    def _get(self, name: str) -> _Stream:
        try:
            return self._streams[name]
        except KeyError:
            raise StreamNotFoundError(name) from None

"""HTTP entry point for StreamMill."""

from __future__ import annotations

import argparse
import json
import math
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

from .service import (
    Service,
    StreamExistsError,
    StreamNotFoundError,
    WatermarkRegressionError,
)


def env_address() -> tuple[str, int]:
    raw = os.environ.get("STREAMMILL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid STREAMMILL_ADDR: {raw!r}")
    return host, int(port)


class _RequestError(Exception):
    """Validation or domain failure mapped onto a JSON error response."""

    def __init__(self, status: int, code: str, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message


def _invalid_request(message: str) -> _RequestError:
    return _RequestError(422, "invalid_request", message)


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_finite_number(value: object) -> bool:
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


_CREATE_FIELDS = {
    "name": lambda v: isinstance(v, str) and len(v) > 0,
    "window_ms": lambda v: _is_int(v) and v > 0,
    "allowed_lateness_ms": lambda v: _is_int(v) and v >= 0,
}
_EVENT_FIELDS = {
    "timestamp_ms": _is_int,
    "value": _is_finite_number,
}
_WATERMARK_FIELDS = {
    "watermark_ms": _is_int,
}


def _validate(body: object, fields: dict) -> dict:
    """Check required fields, types and reject undeclared fields."""
    if not isinstance(body, dict):
        raise _invalid_request("request body must be a JSON object")
    extra = sorted(set(body) - set(fields))
    if extra:
        raise _invalid_request(f"unexpected fields: {', '.join(extra)}")
    values = {}
    for field, check in fields.items():
        if field not in body:
            raise _invalid_request(f"missing required field: {field}")
        value = body[field]
        if not check(value):
            raise _invalid_request(f"invalid value for field: {field}")
        values[field] = value
    return values


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, status: int, code: str, message: str) -> None:
        self.send_json(status, {"error": {"code": code, "message": message}})

    def _segments(self) -> list[str]:
        path = urlsplit(self.path).path
        return [unquote(part) for part in path.split("/") if part]

    def _read_json(self) -> object:
        try:
            length = int(self.headers.get("Content-Length") or "0")
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            return json.loads(raw)
        except ValueError:
            raise _RequestError(400, "invalid_json", "request body is not valid JSON") from None

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        segments = self._segments()
        if len(segments) == 3 and segments[0] == "streams" and segments[2] == "results":
            try:
                self.send_json(200, self.service.results(segments[1]))
            except StreamNotFoundError:
                self.send_error_json(404, "stream_not_found", f"unknown stream: {segments[1]}")
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        segments = self._segments()
        try:
            if segments == ["streams"]:
                self._create_stream()
                return
            if len(segments) == 3 and segments[0] == "streams" and segments[2] == "events":
                self._add_event(segments[1])
                return
            if len(segments) == 3 and segments[0] == "streams" and segments[2] == "watermark":
                self._advance_watermark(segments[1])
                return
        except _RequestError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def _create_stream(self) -> None:
        values = _validate(self._read_json(), _CREATE_FIELDS)
        try:
            payload = self.service.create_stream(
                values["name"], values["window_ms"], values["allowed_lateness_ms"]
            )
        except StreamExistsError:
            raise _RequestError(409, "stream_exists", f"stream already exists: {values['name']}") from None
        self.send_json(201, payload)

    def _add_event(self, name: str) -> None:
        values = _validate(self._read_json(), _EVENT_FIELDS)
        try:
            payload = self.service.add_event(name, values["timestamp_ms"], values["value"])
        except StreamNotFoundError:
            raise _RequestError(404, "stream_not_found", f"unknown stream: {name}") from None
        self.send_json(200, payload)

    def _advance_watermark(self, name: str) -> None:
        values = _validate(self._read_json(), _WATERMARK_FIELDS)
        try:
            payload = self.service.advance_watermark(name, values["watermark_ms"])
        except StreamNotFoundError:
            raise _RequestError(404, "stream_not_found", f"unknown stream: {name}") from None
        except WatermarkRegressionError:
            raise _RequestError(409, "watermark_regression", "watermark must not move backwards") from None
        self.send_json(200, payload)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="streammill.server", description="流式仓库与实时分析引擎")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"StreamMill listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

